// ------------------------------------------------------------ 运行时
const N = TXT.length;
const M = SRC.length;

/** 二分查找句子 i 属于哪个出处。 */
function sourceIndexOf(i) {
  let lo = 0;
  let hi = M - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (SRC_S[mid] <= i) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  return lo;
}

/** 组装一条对外结果。 */
function build(i) {
  return { idx: i, t: TXT[i], f: SRC[sourceIndexOf(i)] || '' };
}

export function init() {
  return N;
}

export function getCount() {
  return N;
}

export function getRandom() {
  if (!N) {
    return null;
  }
  return build((Math.random() * N) | 0);
}

export function getByIndex(i) {
  if (i >= 0 && i < N) {
    return build(i);
  }
  return null;
}

/**
 * 只按“出处”检索。
 * @param {string} kw 关键词，不区分大小写
 * @returns {Array<{idx:number,t:string,f:string}>} 最多 200 条
 */
export function search(kw) {
  const k = String(kw == null ? '' : kw).trim().toLowerCase();
  const out = [];
  if (!k) {
    return out;
  }
  for (let i = 0; i < M; i++) {
    if (SRC[i].toLowerCase().indexOf(k) < 0) {
      continue;
    }
    const end = SRC_S[i + 1];
    for (let j = SRC_S[i]; j < end; j++) {
      out.push(build(j));
      if (out.length >= 200) {
        return out;
      }
    }
  }
  return out;
}

export default { SRC, SRC_S, TXT, init, getCount, getRandom, getByIndex, search };
